 const periods=[
  {id:"auto-2026",date:"Август 2026 - Октябрь 2026",name:"Автомобильная тематика.",role:"Подробности проекта ограничены NDA до 2030 года / Частная практика",desc:"В автомобильный бизнес я пришёл, чтобы проверить себя на прочность. До моего появления многое держалось на сарафанном радио, ручной обработке заявок и практически полном отсутствии цифровых инструментов. За несколько месяцев выстроил брендинг, маркетинговую стратегию, 27 воронок продаж, систему подбора товаров и автоматизацию колл-центра. В отдельных направлениях удалось получить 79 покупок и 127 успешных продаж за два месяца. Здесь я отвечал уже не за отдельный сайт или рекламу, а за то, как работает вся цифровая часть бизнеса. Подробности ограничены NDA до 2030 года.",slugs:["izi-crm","nda-automotive-1","nda-automotive-2","nda-automotive-3"],facts:[["4","дня от начала работы до первых продаж"],["79","покупок в сложной автомобильной нише"],["127","успешных продаж за два месяца"],["481","лид привлечён за четыре месяца"]]},
  {id:"summer-2026",date:"Июнь 2026 - Август 2026",name:"Проектная работа",role:"7 проектов / Lead Product Designer, CPO",desc:"После года работы над одной торговой экосистемой я резко сменил ритм. За неполные три месяца поработал над 14 проектами из совершенно разных сфер: от платёжных систем и CRM до игровых продуктов и аналитики. Где-то отвечал только за дизайн, а где-то подключал разработку и маркетинг. Например, полный цикл дизайна платёжного продукта занял 4 дня, в RSK количество заявок выросло на 21,6%, а для Dead Choices удалось проработать 171 сюжетную сцену. Самым сложным было не количество задач, а необходимость быстро разбираться в новом бизнесе и сразу находить рабочие решения.",slugs:["vremena-goda","rsk","payment-gateway","exocure","pixel-drop","dead-choices","aicors"],facts:[["69","забрендированных наборов и предметов"],["+21,6%","рост числа заявок в RSK"],["4","дня на полный цикл дизайна"],["8","дней на продуктовую логику"],["x4","ускорение разработки"],["171","сюжетная сцена Dead Choices"],["12","дней на полную проработку продукта"]]},
  {id:"hash",date:"Апрель 2025 - Май 2026",name:"Hash Hedge & WSCT",role:"Lead Product Designer",desc:"Всё началось с задачи по разработке рекламной воронки, а закончилось полноценной работой над торговой экосистемой. Больше года я занимался маркетинговым сайтом, личным кабинетом, торговым терминалом, платежами и системой контроля рисков. Только в обновлённом личном кабинете проработал около 465 состояний интерфейса. Отдельным направлением стал WSCT, турнирная платформа для трейдеров, для которой я разработал 6 маркетинговых воронок. Самой интересной частью работы было превращать сложную финансовую логику в интерфейс, которым человек может пользоваться без постоянных объяснений.",slugs:["hash-hedge","wsct"],facts:[["4,8","оценка удобства по опросам"],["6","маркетинговых воронок WSCT"],["465","состояний интерфейса"]]},
  {id:"private-2025",date:"Декабрь 2024 - Апрель 2025",name:"Частная практика",role:"27 проектов / Lead Product Designer, SMM, PCC-Specialist",desc:"После игровых проектов я снова вернулся к частной практике, но теперь брался за гораздо более сложные задачи. В подборку вошли финансовые сервисы, анонимные мессенджеры, медицинские платформы, игровые Telegram Mini Apps и продукты с несколькими ролями. Работал как над отдельными сценариями, так и над полноценными продуктами с нуля. Среди результатов этих проектов: 841 тыс. MAU у Chatus, 217 тыс. MAU у 1Case, 34,2 тыс. прохождений StarHash Benchmark и 182 заявки за неделю у 2Space. Это был период постоянного переключения между индустриями, где времени на долгое погружение практически не оставалось.",slugs:["vlad-bykov","echo-app","twin-finder","propuska","parking","media-garant","chatus","vita-ai","internship-platform","starhash-benchmark","luch","2space","forfis-new-site","digital-lawyer","star-exchange","city-exchange","greenbox","nda-web3","invaprom","onecase","crush","virus","finflow","bill-split","pilots-app","vybor","sailor-planner"],facts:[["841k","MAU у Chatus"],["34,2k","прохождений StarHash Benchmark"],["182","заявки за неделю у 2Space"]]},
  {id:"nutaku",date:"Декабрь 2024 - Февраль 2025",name:"Nutaku Projects (NDA 2026)",role:"5 проектов / UX Designer",desc:"В Nutaku я работал на почасовой ставке, подключался к отдельным задачам по интерфейсам игр 18+, где требовалось переработать UX, игровые механики или монетизацию. Результаты иногда удивляли даже меня. В Horny Villa после переработки магазина количество покупок выросло примерно на 174%, а маркетинговые воронки Poker N Sluts принесли свыше $60 тыс. за три месяца. Для Fab Fantasy спроектировал 712 игровых сцен. Отдельной историей стал My AI Slut, который я практически с нуля собрал и передал заказчику. Ребята занялись продвижением, а спустя время я узнал, что у проекта уже 1,5 млн пользователей. При этом моя работа оставалась именно проектной, без управления командами и постоянного сопровождения продуктов.",slugs:["my-ai-slut","fab-fantasy","poker-n-sluts","horny-villa","desire-inn"],facts:[["1,5M","пользователей My AI Slut позже"],["712","спроектированных игровых сцен"],["$60k","платежей из маркетинговых воронок за три месяца"],["+174%","покупок после UX-редизайна магазина"],["+29%","вовлечённости после UX-доработок"]]},
  {id:"duck",date:"Август 2024 - Декабрь 2024",name:"Duck Master & Game Of Year",role:"Lead Product Designer",desc:"После полутора лет управления большими командами я решил вернуться к созданию продуктов своими руками. В DuckMaster всё началось с небольшого тестового задания, а уже за первые 4 дня я полностью переработал UI/UX игры с аудиторией 3,5 млн MAU. Дальше начались месяцы постоянных релизов, A/B-тестов и развития игровой экономики. Конверсия в первую платную прокрутку выросла с 4% до 19,2%, а D7 Retention с 4% до 39%. Отдельные игровые активности собирали $40–50 тыс. платежей за 96 часов. Позже в рамках той же компании мы за 6 дней создали полностью анимированный MVP Game of Year для инвестора. Именно здесь началось наше сотрудничество с Давидом, которое впоследствии продолжилось в Hash Hedge",slugs:["duckmaster","game-of-year"],facts:[["3,5M","активных пользователей в месяц"],["19,2%","конверсия в первую платную прокрутку"],["6","дней до MVP Game of Year"]]},
  {id:"bonape",date:"Январь 2023 - Август 2024",name:"Bonape & Salute & Artsavur",role:"27 проектов / CEO, PM",desc:"Это был, пожалуй, самый тяжёлый период моей работы. Три направления одной компании: в BONAPE я обучал специалистов и руководил клиентскими проектами, в SALUTE отвечал за маркетинг и трафик, а в ARTSAVUR за дизайн и разработку. В общей сложности под моим прямым руководством было более 50 человек. За это время подготовил 24 специалиста, вместе с командой Apple Bar получили около 700 обращений и 132 оплаченных заказа, а рекламная сеть SALUTE выросла до 31 Telegram-канала с аудиторией 1,6 млн подписчиков. Кроме самих проектов на мне были клиенты, сроки, качество и большая часть сложных решений. В какой-то момент я понял, что практически перестал заниматься тем, ради чего вообще пришёл в эту профессию.",slugs:["bonape-training","apple-bar","slab-service","aquator","rocket-jet","vezu-edu","domodel","ridis","bnqr","x6","winline","salute","artsavur","she-talks","celtway","eurotek","quickpharm","logirus","verbatica","nda-bank","glavbankrot","yacht-center","china-car","fitness-pro","avtoshkola","rdmart","numa"],facts:[["24","специалиста подготовлено"],["132","оплаченных заказа Apple Bar"],["1,6M","подписчиков сети SALUTE"],["50+","сотрудников в прямом подчинении"]]},
  {id:"onlinesklad",date:"Июнь 2022 - Январь 2023",name:"Onlinesklad",role:"Middle Product Designer, QA",desc:"Onlinesklad стал для меня одним из первых крупных проектов, где за внешне обычным маркетплейсом скрывалась сложная внутренняя система. Покупатели, поставщики, каталоги, остатки, заказы и разные сценарии работы с товарами. Я занимался проектированием интерфейсов, пользовательских сценариев, адаптивных состояний и проверкой реализации. Главная сложность была в том, чтобы сохранить понятную логику продукта для разных ролей, не превращая интерфейс в перегруженную систему управления складом.",slugs:["onlinesklad"],facts:[]},
  {id:"sober",date:"Декабрь 2021 - Май 2022",name:"Трезвый Водитель",role:"Middle Product Designer",desc:"В Трезвом Водителе я впервые настолько глубоко погрузился в проектирование сервиса с несколькими пользовательскими ролями. Одной клиентской части здесь было недостаточно: параллельно нужно было продумать приложение водителя, административную систему, работу с заказами, балансами и выплатами. За три месяца продуктом воспользовались около 2 700 пользователей. Главным результатом для меня стала не отдельная красивая часть интерфейса, а полноценная система, в которой все участники работают по одной понятной логике.",slugs:["sober-driver"],facts:[["2 700","пользователей за три месяца"]]},
  {id:"forfis",date:"Ноябрь 2020 - Декабрь 2021",name:"FORFIS AGENCY",role:"15 проектов / Junior Product Designer",desc:"В FORFIS я работал над самыми разными коммерческими задачами: от небольших сайтов и рекламных материалов до интерфейсов сервисов и мобильных приложений. Проекты постоянно менялись, поэтому приходилось быстро разбираться в новой сфере, собирать структуру, проектировать интерфейс, подключать разработку и маркетинг. Именно здесь я начал гораздо серьёзнее относиться к пользовательским сценариям и коммерческим результатам, а не только к визуальной части дизайна. По сути, это был период, когда я постепенно переходил от веб-дизайна к полноценной продуктовой работе.",slugs:["vodacom","psychology","pelikan","fly-ball","restomesto","hamilya-shop","domashniy-doktor","treasures-pskov","history-app","transport-tech","tezgo","pizza-dashboard","deli-she","diary-book","trips"],facts:[]},
  {id:"2020-projects",date:"Январь 2020 - Ноябрь 2020",name:"Частная практика",role:"9 проектов / Web Designer, Marketing",desc:"В 2020 году я начал активно заниматься небольшими коммерческими проектами. Интернет-магазины, каталоги, доставка, сайты для локального бизнеса и первые самостоятельные рекламные кампании. Часто приходилось делать практически всё самому, от идеи и дизайна до запуска и привлечения покупателей. Moonlight получил 537 заявок и 42 продажи, в Mobilka34 по промокодам зафиксировали 3 410 офлайн-продаж, а ИЗЮМ вырос до 522 заказов в месяц. Тогда я впервые на практике увидел, что хороший сайт сам по себе ещё ничего не гарантирует, если за ним не стоит работающая система продаж.",slugs:["myasnoy-dvor","papa-pizza","khleb-iz-tandyra","moonlight","zaryadka","chexolchik","mobilka34","baraholka34","izum"],facts:[["537","заявок Moonlight"],["3 410","офлайн-продаж Mobilka34"],["522","заказа в месяц у ИЗЮМ"]]},
  {id:"media",date:"Сентябрь 2016 - Декабрь 2019",name:"Развитие в медиа & RESTAR",role:"Web Designer, Marketing",desc:"Мой коммерческий опыт начался задолго до работы в продуктовых командах. Сначала были собственные медийные проекты, эксперименты с контентом, продвижением и привлечением аудитории через YouTube и VK. Постепенно это переросло в работу с реальным бизнесом. Одним из первых серьёзных коммерческих проектов стал RESTAR, где я занимался продвижением B2B-продукции. При небольшом рекламном бюджете удалось увеличить количество оплаченных заказов с 2 до 8–9 в год. Тогда я ещё не называл себя продуктовым дизайнером, но уже учился связывать цифровые инструменты с конкретным результатом.",slugs:["restar","vk-media","youtube-1","youtube-2"],facts:[["8–9","оплаченных B2B-заказов в год"]]}
 ];
 const reviews={"auto-2026":[{"id":"felix-g","name":"Felix G.","role":"NDA CEO","lead":"...мне понравился твой подход. Ты относишься к проекту, как к собственному.","body":"Спасибо тебе за работу и мой первый отпуск за 6 лет. Я не верил, что ты сможешь превысить KPI в 4 раза и взять ответственность за свои слова. Жалко с тобой прощаться, но надеюсь скрипты для менеджеров будут работать и без твоего надзора за ребятами.","before":"izi-crm","href":"/cases/automotive/"}],"summer-2026":[{"id":"alexey-rsk","name":"Alexey D.","role":"CEO RSK, ВРЕМЕНА ГОДА","lead":"...Времена года это мое чадо, которое начало работать, благодаря тебе!!","body":"Богдан хороший спец, после него пробовали другие ребята в найме, по итогу его одного смогли заменить только три дизайнера. Полиграфия, баннеры, сайты, реклама, CRM, всё настроил и сделал.","before":"vremena-goda","href":"/cases/vremena-goda/"},{"id":"victor-s","name":"Victor S.","role":"CEO EXOCURE","lead":"Хорошо выносит мозг и отрезвляет, когда глаз становится замыленным.","body":"С этим человеком быстрые звонки могут быть, только если вы не заинтересованы в своём продукте. 5 часов и 31 минуту мы обсуждали тупо один слайд презентации. Круто было поработать с дизайнером, а не очередным сотрудником.","after":"exocure","href":"/cases/exocure/"}],"hash":[{"id":"david-t-hash-hedge","name":"David T.","role":"CPO Hash Hedge","lead":"Богдан, спасибо тебе за всё. Забавно конечно начинали с утки, а в итоге столько всего сделали в Hash Hedge.","body":"С тобой реально было приятно работать, можно спокойно доверить задачу и не переживать за итог. Правда со сроками ты меня иногда подставлял ахах) За неделю делал месячный бэклог, а мне потом на тебя другие отделы жаловались.","after":"wsct","href":"/cases/hash-hedge/"}],"private-2025":[{"id":"vlad-b","name":"Vlad B.","role":"Заказчик","lead":"Let's put it this way. I'm a picky client, but only when it comes to incompetent designers who use AI instead of their own hands and eyes.","body":"You're a good designer, but you lack some fucking flexibility. Your website works well, but mine is good too.","after":"vlad-bykov","href":"/cases/vlad-bykov/"},{"id":"denis-k","name":"Denis K.","role":"Art Director Chatus","lead":"Приятный человек и классный дизайнер.","body":"Поработав вместе с тобой на проекте, понял, почему тебя рекомендовали к нам. Наши с тобой отношения сложно назвать хорошими, но работу мы сделали супер быстро и отставание дизайна на 1,5 месяца догнали за неделю.","after":"echo-app","href":"/cases/chatus/"},{"id":"evgenii-g","name":"Evgenii G.","role":"Director GreenBox","lead":"...мой совет — работать с ним легко стало, когда дал ему полное согласие на всё...","body":"Продать газоны летом может каждый, а вот не в сезон звучит глупо. Богдана нашёл случайно, через знакомых, хотел к лету подготовиться, но он решил сделать запуск зимой. Теперь брони до 2027 года, короче советую поработать хоть раз с ним.","after":"greenbox","href":"/cases/greenbox/"}],"nutaku":[{"id":"alex","name":"Alex","role":"CPO Filth Fruits","lead":"Solid guy, honest as hell and knows his stuff even on complex projects.","body":"Bogdan was billing us hourly and let's be real, people love padding their hours lol. Not this guy tho. He'd actually cut his own time saying the job was too easy. Never had to question a single invoice. Mad respect for that.","after":"my-ai-slut","href":"/projects/"}],"duck":[{"id":"david-t-duckmaster","name":"David T.","role":"CPO DuckMaster","lead":"Рады были поработать с тобой на проекте. Не ожидал, что за сутки ты пересоберёшь проект или его визуальное исполнение.","body":"Когда смотрели твоё портфолио, были не уверены, что ты приживёшься у нас. В итоге за месяц мы изменили с тобой проект до какого-то неузнаваемого уровня. Надеюсь ещё поработать с тобой в будущем!","before":"duckmaster","href":"/cases/duckmaster/"}],"bonape":[{"id":"alexander-b","name":"Alexander B.","role":"Founder Apple Bar","lead":"Команда Bonape удивила меня своей любовью к делу.","body":"У нас была офлайн-точка по продаже телефонов в Волгограде, бизнес рос, но медленно. Посоветовали Богдана с его компанией, за три недели сделали сайт-каталог в нужном стиле, а после запустили рекламу. Более 500 заказов за месяц работы, спасибо вам!","after":"apple-bar","href":"/cases/apple-bar/"},{"id":"sardal-r","name":"Sardal R.","role":"Director Slab Service","lead":"РАБОТА СДЕЛАНА НА 5+!","body":"Мы продаём и устанавливаем декоративную плитку в Москве. Конкуренция тут большая, но ребята справились. Очень хотел получать клиентов без вливания миллионов в рекламу. Настроили поиск, Яндекс, ВКонтакте и Одноклассники, через месяц всё отлично заработало, клиентов куча. Радостно было работать с вами!!","after":"slab-service","href":"/cases/slab-service/"}],"onlinesklad":[{"id":"almira-m","name":"Almira M.","role":"CPO Onlinesklad","lead":"...думала, что он слишком усложняет, но потом поняла, что именно благодаря этому мы половину интерфейса не переделывали.","body":"Богдану нельзя сказать, что нам нужен каталог товаров, он сразу начнёт спрашивать: а что если у товара пять поставщиков, разные цены, остатки? А если возврат? И так до бесконечности)","after":"onlinesklad","href":"/cases/onlinesklad/"},{"id":"sergey-j","name":"Sergey J.","role":"Founder Onlinesklad","lead":"Богдан показал себя как грамотный и ответственный специалист.","body":"Хорошо разобрался в специфике нашего продукта, самостоятельно находил проблемы и предлагал решения. Работа выполнена качественно, в согласованные сроки. Результатом доволен.","after":"almira-m","href":"/cases/onlinesklad/"}],"sober":[{"id":"evgenii-y","name":"Evgenii Y.","role":"Founder Sober Driver","lead":"Добротную работу делает, помог найти нам подрядчиков на разные задачи.","body":"Пришёл с командой, остался один на проекте и вытащил его из идеи до готового продукта. Справился с 176-страничным документом правок от новых подрядчиков, спасибо за работу, ещё позовём.","after":"sober-driver","href":"/cases/sober-driver/"}],"media":[{"id":"elena-s","name":"Elena S.","role":"CEO RESTAR & Mom Slepzof :)","lead":"Ответственный парень, который любит свою работу.","body":"Богдан с детства такой, если ему что-то действительно интересно, он может сутками сидеть, разбираться, пока не получится. Ответственный и исполнительный. Но иногда бывает ужасно ленивым, особенно если не видит смысла в том, что делает. Зато когда появляется цель, его уже не остановить.","after":"restar","href":"/cases/restar/"}]};
